def _eval_is_zero(self):
    if self.is_commutative is False:
        return
    real_terms = []
    imag_terms = []
    real_zero_count = 0
    for a in self.args:
        if a.is_real:
            if a.is_zero:
                real_zero_count += 1
            elif a.is_zero is False:
                real_terms.append(a)
            else:
                return
        elif a.is_imaginary or (S.ImaginaryUnit*a).is_real:
            imag_terms.append(a)
        else:
            return
    total = len(self.args)
    if real_zero_count == total:
        return True
    # if all terms are real and non‑zero and no imaginary parts
    if not imag_terms and len(real_terms) == total:
        return None
    # evaluate real and imaginary parts separately
    real_sum = self.func(*real_terms) if real_terms else S.Zero
    imag_sum = self.func(*imag_terms) if imag_terms else S.Zero
    # if both parts are known to be zero
    if real_sum.is_zero and imag_sum.is_zero:
        return True
    # if either part is known to be non‑zero
    if real_sum.is_zero is False or imag_sum.is_zero is False:
        return False
    # otherwise undecided
    return None
